using System.Drawing;
using System.IO;
namespace JanusDock;
// Reduced copies of the owner's three supplied PNG assets. No generated substitutions.
internal static class PowerImages
{
 const string Lock = "";
 const string Restart = "";
 const string Shutdown = "";
 public static Image Load(string action)
 {
  string encoded = action switch { "janus:lock" => Lock, "janus:restart" => Restart, _ => Shutdown };
  using var stream = new MemoryStream(Convert.FromBase64String(encoded));
  using var image = Image.FromStream(stream);
  return new Bitmap(image);
 }
 public static Image Load(bool shutdown) => Load(shutdown ? "janus:shutdown" : "janus:restart");
}
